// vgui CWin32Font::Create only takes a face EnumFontFamiliesEx can see, else it falls back.
// AddFontMemResourceEx fonts are never enumerated; an AddFontResourceEx FR_PRIVATE file font is
// (GDI checked 11-10). So the bytes go to %TEMP% and get added from there, once per process.
// A failed write (another TF2 holds the same file) still adds the copy already there.
inline bool Stratum2Otf_Register()
{
    static const bool ok = [] {
        char path[MAX_PATH];
        const DWORD n = GetTempPathA(MAX_PATH, path);
        if (!n || n + 32 > MAX_PATH) return false;
        strcat_s(path, "botox_stratum2_bold.otf");
        HANDLE h = CreateFileA(path, GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
        if (h != INVALID_HANDLE_VALUE)
        {
            DWORD wr = 0;
            WriteFile(h, stratum2_bold_otf, sizeof(stratum2_bold_otf), &wr, nullptr);
            CloseHandle(h);
        }
        return AddFontResourceExA(path, FR_PRIVATE, nullptr) > 0;
    }();
    return ok;
}
